import {
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  positionLocal,
  uv,
  vec3,
  vec4,
  mix,
  smoothstep,
  length,
  float,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const {
    Group,
    Mesh,
    TorusKnotGeometry,
    CylinderGeometry,
    PlaneGeometry,
    CircleGeometry,
    DirectionalLight,
    Color,
  } = THREE;

  const group = new Group();
  group.name = 'pedestal-material-study';

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#0b0b10' },
      { at: 0.7, hex: '#101017' },
      { at: 1, hex: '#16161d' },
    ],
  };

  const stops = colors.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 1, hex: '#16161d' },
  ];

  // ---------- Backdrop with vertical gradient ----------
  const cBottom = new Color(stops[0].hex);
  const cMid = new Color(stops[Math.min(1, stops.length - 1)].hex);
  const cTop = new Color(stops[stops.length - 1].hex);

  const backdropMat = new MeshBasicNodeMaterial();
  {
    const v = uv().y;
    const lower = mix(vec3(cBottom.r, cBottom.g, cBottom.b), vec3(cMid.r, cMid.g, cMid.b), smoothstep(0.0, 0.7, v));
    const grad = mix(lower, vec3(cTop.r, cTop.g, cTop.b), smoothstep(0.7, 1.0, v));
    backdropMat.colorNode = vec4(grad, float(1.0));
    backdropMat.toneMapped = false;
  }
  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMat);
  backdrop.position.set(0, 0, -3);
  group.add(backdrop);

  // ---------- Pedestal ----------
  const pedestalMat = new MeshStandardNodeMaterial();
  pedestalMat.color = new Color(colors.surface || '#14141a');
  pedestalMat.roughness = 0.7;
  pedestalMat.metalness = 0.35;
  const pedestal = new Mesh(new CylinderGeometry(1.1, 1.12, 0.5, 64, 1, false), pedestalMat);
  // top face at y=-0.35 -> center at -0.35 - 0.25 = -0.6
  pedestal.position.set(0, -0.6, 0);
  group.add(pedestal);

  // chamfer ring catching key light
  const chamferMat = new MeshStandardNodeMaterial();
  chamferMat.color = new Color(colors.surface || '#14141a');
  chamferMat.roughness = 0.45;
  chamferMat.metalness = 0.5;
  const chamfer = new Mesh(new CylinderGeometry(1.1, 1.14, 0.03, 64, 1, false), chamferMat);
  chamfer.position.set(0, -0.365, 0);
  group.add(chamfer);

  // ---------- Contact shadow ----------
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  {
    const d = length(uv().sub(0.5)).mul(2.0);
    const a = smoothstep(1.0, 0.0, d).mul(0.6);
    shadowMat.colorNode = vec4(vec3(0.0, 0.0, 0.0), a);
    shadowMat.toneMapped = false;
  }
  const shadow = new Mesh(new CircleGeometry(1.5, 64), shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.36, 0);
  group.add(shadow);

  // ---------- Torus knot (hero) ----------
  const knotMat = new MeshPhysicalNodeMaterial();
  knotMat.color = new Color('#c9ccd2');
  knotMat.roughness = 0.55;
  knotMat.metalness = 0.55;
  knotMat.clearcoat = 0.22;
  knotMat.clearcoatRoughness = 0.35;
  if ('anisotropy' in knotMat) {
    knotMat.anisotropy = 0.9;
    knotMat.anisotropyRotation = Math.PI / 2;
  }

  const knot = new Mesh(new TorusKnotGeometry(0.7, 0.22, 220, 36), knotMat);
  knot.position.set(0, 0.4, 0);
  group.add(knot);

  // brushed-metal roughness map (map multiplies, swap-proof)
  const baseRough = 0.55;
  ctx.textureLoader
    .loadTexture(config.imageUrl || '/prism-assets/chrome/brushed-metal.map.png')
    .then((tex) => {
      tex.wrapS = THREE.RepeatWrapping;
      tex.wrapT = THREE.RepeatWrapping;
      knotMat.roughnessMap = tex;
      knotMat.roughness = baseRough;
      knotMat.needsUpdate = true;
    })
    .catch(() => {});

  // ---------- Node-local lights ----------
  const key = new DirectionalLight(0xffffff, 1.2);
  key.position.set(3, 4, 4);
  group.add(key);

  const rim = new DirectionalLight(new Color(colors.accent || '#ff2a38'), 1.0);
  rim.position.set(-4, 2.5, -3);
  group.add(rim);

  // ---------- Text ----------
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'Material study 03', role: 'headline' },
      { text: 'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT', role: 'caption' },
    ];

  const textMeshes = [];
  for (const item of items) {
    if (!item || !item.text) continue;
    const role = item.role || 'caption';
    let mesh;
    if (role === 'headline') {
      mesh = ctx.fontAtlas.createText(String(item.text), {
        fontSize: 68,
        color: colors.paper || '#e8ecf2',
        align: 'center',
      });
      mesh.position.set(0, -1.2, 0.1);
    } else {
      mesh = ctx.fontAtlas.createText(String(item.text), {
        fontSize: 18,
        color: colors.paper || '#e8ecf2',
        align: 'center',
        letterSpacingPx: 2,
      });
      mesh.position.set(0, -1.6, 0.1);
    }
    group.add(mesh);
    textMeshes.push(mesh);
  }

  // ---------- Entrance motion ----------
  const tls = [];
  knot.scale.setScalar(1.04);
  const settle = gsap.to(knot.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  tls.push(settle);

  for (let i = 0; i < textMeshes.length; i++) {
    const m = textMeshes[i];
    const baseY = m.position.y;
    m.position.y = baseY + 0.3;
    const t = gsap.to(m.position, {
      y: baseY,
      duration: 0.7,
      delay: 0.1 + i * 0.08,
      ease: 'power3.out',
    });
    tls.push(t);
  }

  // ---------- Cinematic primitives ----------
  const primResults = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    const fn = ctx.primitives?.[p.name];
    if (typeof fn === 'function') {
      const target = p.name === 'orbit' ? knot : group;
      const r = fn(target, p.params || {});
      if (r) primResults.push(r);
    }
  }

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    for (const t of tls) t.kill?.();
    for (const r of primResults) r.cleanup?.();
    group.traverse((obj) => {
      if (obj.isMesh) {
        obj.geometry?.dispose?.();
        const m = obj.material;
        if (Array.isArray(m)) m.forEach((mm) => mm.dispose?.());
        else m?.dispose?.();
      }
    });
    if (knotMat.roughnessMap) knotMat.roughnessMap.dispose?.();
  };

  return group;
}
